#!/usr/bin/env bash
# Check generated-package provenance and overlay boundaries across packages/*/src.
#
# Rules enforced:
#   1. Every file starting with `// GENERATED BY mbt2pion` must declare valid 40-char lowercase
#      hex `mbt2pion_commit` and `source_commit` headers (rejects `dev` / `working-tree`).
#   2. Any package containing at least one generated file is a "generated package":
#      non-generated `.pion` files inside it are restricted to:
#        - `*_test.pion`
#        - `zz_invar_*.pion`
#        - `invar_ext.pion`
#        - `00_init_order.pion` (topological init order file)
#   3. Ratcheting baseline: known pre-existing legacy items (pending next publish wave) are
#      listed in BASELINE_* below so the gate passes on HEAD while strictly rejecting ANY new
#      invalid header, ANY new non-overlay file, or stale baseline entries after cleanup.
#      Pass `--strict` to disable all baseline exemptions.
#
# Usage:
#   bash scripts/check-generated.sh [--strict] [--report-only] [--require-single-commit] [--json]

set -euo pipefail

ROOT_DIR="$(cd "$(dirname "$0")/.." && pwd)"
STRICT=0
REPORT_ONLY=0
REQUIRE_SINGLE=0
JSON_OUT=0

for arg in "$@"; do
  case "$arg" in
    --strict) STRICT=1 ;;
    --report-only) REPORT_ONLY=1 ;;
    --require-single-commit) REQUIRE_SINGLE=1 ;;
    --json) JSON_OUT=1 ;;
    -h|--help)
      sed -n '2,20p' "$0"
      exit 0
      ;;
    *)
      echo "Unknown argument: $arg" >&2
      exit 2
      ;;
  esac
done

python3 - "$ROOT_DIR" "$STRICT" "$REPORT_ONLY" "$REQUIRE_SINGLE" "$JSON_OUT" <<'PY'
import json
import os
import re
import sys

root = sys.argv[1]
strict = sys.argv[2] == "1"
report_only = sys.argv[3] == "1"
require_single = sys.argv[4] == "1"
json_out = sys.argv[5] == "1"

HEX40 = re.compile(r"^[0-9a-f]{40}$")
ALLOWED_HAND_EXACT = {"00_init_order.pion", "invar_ext.pion"}

# Ratcheting baseline of pre-existing legacy violations (exact file paths; may only shrink, never grow).
# Remove each entry as soon as its file is republished with valid 40-char hex headers or renamed.
BASELINE_BAD_HEADER_FILES = {
    "packages/headless/src/00_init_order.pion",
    "packages/headless/src/accordion.pion",
    "packages/headless/src/anchor.pion",
    "packages/headless/src/button.pion",
    "packages/headless/src/choice.pion",
    "packages/headless/src/cmdk.pion",
    "packages/headless/src/combobox.pion",
    "packages/headless/src/context_menu.pion",
    "packages/headless/src/dialog.pion",
    "packages/headless/src/disclosure.pion",
    "packages/headless/src/drawer.pion",
    "packages/headless/src/focus_recovery.pion",
    "packages/headless/src/headless.pion",
    "packages/headless/src/hover_reveal.pion",
    "packages/headless/src/inline_edit.pion",
    "packages/headless/src/input_history.pion",
    "packages/headless/src/listbox.pion",
    "packages/headless/src/menu.pion",
    "packages/headless/src/menubar.pion",
    "packages/headless/src/number_input.pion",
    "packages/headless/src/overlay.pion",
    "packages/headless/src/popover.pion",
    "packages/headless/src/progress.pion",
    "packages/headless/src/radio_group.pion",
    "packages/headless/src/range_slider.pion",
    "packages/headless/src/reorder.pion",
    "packages/headless/src/repeat.pion",
    "packages/headless/src/rove.pion",
    "packages/headless/src/selection.pion",
    "packages/headless/src/shortcut.pion",
    "packages/headless/src/slider.pion",
    "packages/headless/src/split.pion",
    "packages/headless/src/state_set.pion",
    "packages/headless/src/submenu.pion",
    "packages/headless/src/swipe_actions.pion",
    "packages/headless/src/table.pion",
    "packages/headless/src/tabs.pion",
    "packages/headless/src/text_field.pion",
    "packages/headless/src/toaster.pion",
    "packages/headless/src/toggle.pion",
    "packages/headless/src/toggle_group.pion",
    "packages/headless/src/toolbar.pion",
    "packages/headless/src/tooltip.pion",
    "packages/headless/src/tree.pion",
    "packages/headless/src/trigger_menu.pion",
    "packages/headless/src/typeahead.pion",
}
BASELINE_ROGUE_FILES = set()

def is_allowed_overlay(fname: str) -> bool:
    return (
        fname.endswith("_test.pion")
        or fname.startswith("zz_invar_")
        or fname in ALLOWED_HAND_EXACT
    )

packages_dir = os.path.join(root, "packages")
bad_headers = []
rogue_files = []
pkg_commits = {}
gen_packages = 0
gen_files_total = 0

for pkg in sorted(os.listdir(packages_dir)):
    src_dir = os.path.join(packages_dir, pkg, "src")
    if not os.path.isdir(src_dir):
        continue
    pion_files = []
    for dirpath, _, filenames in os.walk(src_dir):
        for fn in sorted(filenames):
            if fn.endswith(".pion"):
                rel_in_src = os.path.relpath(os.path.join(dirpath, fn), src_dir).replace(os.sep, "/")
                pion_files.append((rel_in_src, fn, os.path.join(dirpath, fn)))
    pion_files.sort()

    gen_in_pkg = []
    hand_in_pkg = []
    commits = set()

    for rel_in_src, fname, fpath in pion_files:
        with open(fpath, "r", encoding="utf-8", errors="replace") as fh:
            head_lines = [fh.readline().strip() for _ in range(12)]
        if head_lines and head_lines[0].startswith("// GENERATED BY mbt2pion"):
            gen_in_pkg.append(rel_in_src)
            gen_files_total += 1
            mbt2pion_c = None
            source_c = None
            for ln in head_lines:
                if ln.startswith("// mbt2pion_commit:"):
                    mbt2pion_c = ln.split(":", 1)[1].strip()
                elif ln.startswith("// source_commit:"):
                    source_c = ln.split(":", 1)[1].strip()
            if not mbt2pion_c or not HEX40.match(mbt2pion_c):
                bad_headers.append({
                    "pkg": pkg,
                    "file": f"packages/{pkg}/src/{rel_in_src}",
                    "field": "mbt2pion_commit",
                    "value": mbt2pion_c or "<missing>",
                })
            if not source_c or not HEX40.match(source_c):
                bad_headers.append({
                    "pkg": pkg,
                    "file": f"packages/{pkg}/src/{rel_in_src}",
                    "field": "source_commit",
                    "value": source_c or "<missing>",
                })
            if source_c:
                commits.add(source_c)
        else:
            hand_in_pkg.append((rel_in_src, fname))

    if gen_in_pkg:
        gen_packages += 1
        pkg_commits[pkg] = sorted(commits)
        for rel_in_src, fname in hand_in_pkg:
            if not is_allowed_overlay(fname):
                rogue_files.append(f"packages/{pkg}/src/{rel_in_src}")

distinct_commits = sorted({c for cs in pkg_commits.values() for c in cs})
skew_error = require_single and len(distinct_commits) > 1

# Evaluate against strict mode or ratcheting baseline
new_bad_headers = []
new_rogue_files = []
stale_baseline = []

if strict:
    new_bad_headers = bad_headers
    new_rogue_files = rogue_files
else:
    bad_header_files = {h["file"] for h in bad_headers}
    for h in bad_headers:
        if h["file"] not in BASELINE_BAD_HEADER_FILES:
            new_bad_headers.append(h)
    for bf in sorted(BASELINE_BAD_HEADER_FILES):
        if bf not in bad_header_files:
            stale_baseline.append(f"BASELINE_BAD_HEADER_FILES: '{bf}' resolved (remove it!)")

    rogue_set = set(rogue_files)
    for rf in rogue_files:
        if rf not in BASELINE_ROGUE_FILES:
            new_rogue_files.append(rf)
    for rf in sorted(BASELINE_ROGUE_FILES):
        if rf not in rogue_set:
            stale_baseline.append(f"BASELINE_ROGUE_FILES: '{rf}' resolved (remove it!)")

ok = (
    len(new_bad_headers) == 0
    and len(new_rogue_files) == 0
    and len(stale_baseline) == 0
    and (not skew_error)
)

report = {
    "ok": ok,
    "strict": strict,
    "generated_packages": gen_packages,
    "generated_files": gen_files_total,
    "distinct_source_commits": distinct_commits,
    "package_source_commits": pkg_commits,
    "bad_headers_count": len(bad_headers),
    "new_bad_headers_count": len(new_bad_headers),
    "new_bad_headers": new_bad_headers,
    "rogue_files_count": len(rogue_files),
    "new_rogue_files": new_rogue_files,
    "stale_baseline": stale_baseline,
}

if json_out:
    print(json.dumps(report, indent=2, ensure_ascii=False))
else:
    mode = "strict" if strict else "ratchet"
    print(f"[{mode}] Generated packages: {gen_packages} ({gen_files_total} files), distinct source_commit: {len(distinct_commits)}")
    for pkg, cs in pkg_commits.items():
        print(f"  - {pkg}: {', '.join(cs)}")
    if new_bad_headers:
        print(f"\nFAIL: {len(new_bad_headers)} unbaselined invalid generated header(s):")
        for h in new_bad_headers[:20]:
            print(f"  {h['file']}: {h['field']} = {h['value']}")
        if len(new_bad_headers) > 20:
            print(f"  ... and {len(new_bad_headers) - 20} more")
    if new_rogue_files:
        print(f"\nFAIL: {len(new_rogue_files)} unbaselined non-overlay hand-written file(s) in generated packages:")
        for rf in new_rogue_files:
            print(f"  {rf}")
    if stale_baseline:
        print("\nFAIL: stale baseline entries (shrink baseline now):")
        for s in stale_baseline:
            print(f"  {s}")
    if skew_error:
        print(f"\nFAIL: cross-package source_commit skew ({len(distinct_commits)} commits)")
    if ok:
        if not strict and (bad_headers or rogue_files):
            print(f"\nPASS (ratchet): 0 new violations (legacy baseline: {len(bad_headers)} headers in headless, {len(rogue_files)} legacy file).")
        else:
            print("\nPASS: generated-package provenance and overlay boundaries clean.")

if not report_only and not ok:
    sys.exit(1)
PY
